INSERT INTO `chat_messages` (`id`, `session_id`, `role`, `content`, `artifacts`) VALUES (48,18,'assistant','结论：我可以帮你学习和演练售后客服的常见工作，但当前未连接店铺知识库、订单查询或售后工具，不能查订单或执行实际操作。\n\n我能做的三件事：\n1. 讲解售后客服知识：退换货沟通思路、话术结构、情绪安抚、升级处理原则。\n2. 模拟客服对话：你扮演顾客或客服，我陪你演练并点评改进。\n3. 帮你整理回复草稿：根据你提供的订单/规则信息，起草沟通话术；具体政策需你补充店铺依据。',NULL);
