INSERT INTO `chat_messages` (`id`, `session_id`, `role`, `content`, `artifacts`) VALUES (50,18,'assistant','结论：你发的“111”信息不足，我无法判断你想咨询什么。\n\n请补充具体问题，例如：\n1. 你想了解哪类售后问题（退换货、物流、退款等）？\n2. 涉及哪个订单或商品（可提供订单号/商品名）？\n3. 你希望我帮你梳理处理思路，还是生成客服回复话术？\n\n目前未连接店铺知识库和订单工具，具体政策需以店铺实际规则为准。',NULL);
