INSERT INTO `chat_messages` (`id`, `session_id`, `role`, `content`, `artifacts`) VALUES (550,216,'assistant','导出完成。\n\n- 范围：2026-11-01 至 2026-11-17（按下单时间），共 6 笔订单。\n- 文件：订单_2026-11-01_2026-11-17.xlsx，可在文件卡片下载，有效期 24 小时。\n- 如需按支付或发货时间筛选，或缩小到某个状态、商品，告诉我即可。','[{\"kind\": \"export\", \"rows\": [], \"draft\": null, \"title\": \"订单 Excel 导出\", \"columns\": [], \"filename\": \"订单_2026-11-01_2026-11-17.xlsx\", \"export_id\": \"aedd5655-2a64-44be-bfbc-cca3200b1643\", \"row_count\": 6, \"truncated\": false, \"expires_at\": 1794991922, \"missing_fields\": []}]');
