CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '订单主键',
  `order_no` varchar(32) NOT NULL COMMENT '订单编号',
  `user_id` int NOT NULL COMMENT '订单归属用户',
  `product` varchar(128) NOT NULL COMMENT '模拟商品名称',
  `status` varchar(32) NOT NULL COMMENT '模拟订单状态',
  `quantity` int DEFAULT NULL COMMENT '数量',
  `unit_price` decimal(12,2) DEFAULT NULL COMMENT '商品单价（元）',
  `discount_amount` decimal(12,2) DEFAULT NULL COMMENT '优惠金额（元）',
  `shipping_fee` decimal(12,2) DEFAULT NULL COMMENT '运费（元）',
