  `paid_at` datetime DEFAULT NULL COMMENT '付款时间',
  `shipped_at` datetime DEFAULT NULL COMMENT '发货时间',
  `delivered_at` datetime DEFAULT NULL COMMENT '签收时间',
  `recipient_name` varchar(64) DEFAULT NULL COMMENT '合成收货人',
  `recipient_phone` varchar(32) DEFAULT NULL COMMENT '合成联系电话',
  `province` varchar(32) DEFAULT NULL COMMENT '收货省份',
  `city` varchar(32) DEFAULT NULL COMMENT '收货城市',
  `district` varchar(32) DEFAULT NULL COMMENT '收货区县',
  `address` varchar(256) DEFAULT NULL COMMENT '收货详细地址',
  `shipping_company` varchar(64) DEFAULT NULL COMMENT '物流公司',
  `tracking_no` varchar(64) DEFAULT NULL COMMENT '合成物流单号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  KEY `ix_orders_user_id` (`user_id`),
  KEY `ix_orders_user_created` (`user_id`,`created_at`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21015 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
